imageHint: "Triglav mountain peak in Julian Alps",
    descriptionAdvanced: {
      de: "Der Triglav ist mit 2.864 Metern der höchste Gipfel der Julischen Alpen und der höchste Berg Sloweniens. Er ist ein zentrales nationales Symbol und ist sowohl im Staatswappen als auch auf der Nationalflagge abgebildet. Der Berg gab dem einzigen Nationalpark des Landes, dem Triglav-Nationalpark, seinen Namen, der fast das gesamte Gebiet der östlichen Julischen Alpen umfasst. Auf dem Gipfel steht der berühmte Aljaž-Turm, ein kleiner Metallturm, der 1895 von dem Priester Jakob Aljaž errichtet wurde und heute als geschütztes Kulturdenkmal gilt. Der Triglav ist für Bergsteiger eine Herausforderung und ein stolzes Ziel; es heißt traditionell, dass jeder echte Slowene mindestens einmal im Leben auf seinem Gipfel gestanden haben muss. Geologisch besteht der Berg überwiegend aus Kalkstein, was zu spektakulären Karstformationen und tiefen Abgründen führt. Das Panorama vom Gipfel reicht an klaren Tagen von der Adria bis zu den österreichischen Alpen. Trotz seiner Beliebtheit erfordert der Aufstieg alpine Erfahrung und gute Vorbereitung, da die Wetterbedingungen im Hochgebirge sehr wechselhaft sein können.",
      hu: "A Triglav 2864 méteres magasságával a Júliai-Alpok és egyben Szlovénia legmagasabb csúcsa. Az ország egyik legfontosabb nemzeti szimbóluma, amely a szlovén címerben és a nemzeti zászlón is szerepel. A hegyről kapta nevét az ország egyetlen nemzeti parkja, a Triglav Nemzeti Park, amely a Keleti-Júliai-Alpok szinte teljes területét lefedi. A csúcson áll a híres Aljaž-torony, egy kis fémhenger, amelyet Jakob Aljaž pap állíttatott 1895-ben, és mára védett kulturális műemléknek számít. A Triglav megmászása minden szlovén számára büszkeség; a hagyomány szerint minden 'igazi' szlovénnek legalább egyszer életében fel kell jutnia a csúcsra. A hegy geológiailag főként mészkőből épül fel, ami látványos karsztformákat és mély szakadékokat eredményezett. Tiszta időben a kilátás az Adriai-tengertől egészen az osztrák Alpokig terjed. Bár rendkívül népszerű túracélpont, a csúcs elérése hegymászó tapasztalatot és jó állóképességet igényel, mivel az időjárási körülmények hirtelen változhatnak.",
      ro: "Triglav este cel mai înalt vârf din Alpii Iulieni și din Slovenia, atingând o altitudine de 2.864 de metri. Muntele reprezintă un simbol național suprem, fiind reprezentat atât pe stema de stat, cât și pe steagul național. Acesta dă numele singurului parc național al țării, Parcul Național Triglav, care protejează o mare parte din estul Alpilor Iulieni. Pe vârful muntelui se află Turnul Aljaž, o structură metalică mică ridicată în 1895 de preotul Jakob Aljaž, considerată astăzi un monument cultural protejat. Escaladarea Triglavului este o chestiune de mândrie națională; se spune că fiecare 'adevărat sloven' trebuie să ajungă pe vârf cel puțin o dată în viață. Geologia muntelui este predominant calcaroasă, ceea ce a dus la formarea unor peisaje carstice spectaculoase și a unor pereți verticali impunători. Panorama de pe vârf, în zilele senine, se întinde de la Marea Adriatică până la crestele Alpilor austrieci. În ciuda popularității sale, ascensiunea necesită echipament adecvat și experiență montană, condițiile meteo fiind adesea imprevizibile la această altitudine.",
      en: "Triglav, standing at 2,864 meters, is the highest peak in the Julian Alps and the national mountain of Slovenia. It is a central national symbol, featured prominently on both the country's coat of arms and its national flag. The mountain gives its name to Slovenia's only national park, Triglav National Park, which covers nearly the entire area of the Eastern Julian Alps. At the very summit stands the Aljaž Tower, a small metal structure erected in 1895 by the priest Jakob Aljaž, now a protected cultural monument and a primary landmark for climbers. Reaching the peak of Triglav is considered a rite of passage for Slovenians; tradition holds that every true Slovenian must stand atop the mountain at least once. Geologically, the mountain is composed mostly of limestone, resulting in dramatic karst formations and sheer rock faces. On clear days, the summit offers panoramic views extending from the Adriatic Sea to the Austrian Alps. While highly popular, the climb to the top is physically demanding and requires proper alpine experience due to the rugged terrain and variable weather.",
      es: "Triglav es el pico más alto de Eslovenia con 2864 metros y un símbolo nacional. Forma el corazón del único parque nacional del país en los Alpes Julianos.",
      pt: "Triglav é o pico mais alto da Eslovénia com 2864 metros e um símbolo nacional. Forma o coração do único parque nacional do país nos Alpes Julianos.",
      fr: "Le Triglav est le plus haut sommet de Slovénie avec 2864 mètres et un symbole national. Il forme le cœur du seul parc national du pays dans les Alpes juliennes.",
    },
