      de: ["Fläche variiert zwischen 0 und 38 km²", "Wichtiges Beispiel für Karstphänomene", "Lebensraum für die seltene Rohrdommel", "Schon von Valvasor im 17. Jh. beschrieben"],
      hu: ["Területe 0 és 38 km² között változik", "Világszerte a karsztjelenségek egyik fő példája", "A ritka bölömbika fészkelőhelye", "Valvasor már a 17. században tanulmányozta"],
      ro: ["Suprafața variază între 0 și 38 km²", "Exemplu clasic de fenomen hidrologic carstic", "Loc de cuibărit pentru buhaiul de baltă", "Descris detaliat de Valvasor în secolul al XVII-lea"],
