      pt: ["O pico mais alto é o Blegoš (1562 m)", "Conhecido pela produção tradicional de queijo", "Zona de caminhadas popular perto de Liubliana", "Contém restos da linha defensiva Rupnik"],
      fr: ["Le sommet le plus haut est le Blegoš (1562 m)", "Connu pour la fabrication traditionnelle de fromage", "Zone de randonnée populaire près de Ljubljana", "Contient les restes de la ligne de défense Rupnik"],
