      ro: ["Cel mai înalt vârf este Ratitovec la 1678 metri", "Cunoscut pentru Blegoš, un munte popular pentru panoramă", "Regiunea are o tradiție îndelungată în prelucrarea fierului", "Găzduiește cele mai vechi spectacole de Paște din Slovenia (Škofja Loka)", "Peisaj marcat de harfele de fân tradiționale numite 'toplar'", "Coridor important pentru fauna sălbatică precum cerbi și capre negre"],
