      de: "Die Karawanken bilden eine natürliche Grenze zwischen Slowenien und Österreich. Mit über 120 Kilometern Länge sind sie eine der längsten Gebirgsketten Europas.",
      hu: "A Karavankák hegylánca természetes határt alkot Szlovénia és Ausztria között. 120 kilométeres hosszával Európa egyik leghosszabb összefüggő hegyvonulata.",
