      pt: ["Temperatura da água constante de aprox. 6°C", "O nome significa 'os verdes' em esloveno", "Centro de uma zona húmida com alta biodiversidade", "Inspiração para o investigador Humphry Davy"],
      fr: ["Température de l'eau constante d'environ 6°C", "Le nom signifie 'les verts' en slovène", "Centre d'une zone humide avec une biodiversité élevée", "Inspiration pour le chercheur Humphry Davy"],
