    imageHint: "Zelenci nature reserve emerald lake Alps",
    descriptionAdvanced: {
      de: "Das Naturreservat Zelenci liegt am westlichen Rand des Dorfes Podkoren und ist bekannt als die Quelle der Sava Dolinka, eines der Hauptquellflüsse der Save. Das Herzstück des Reservats ist ein kleiner, smaragdgrüner See, der aus zahlreichen Unterwasserquellen im kreidigen Seeboden gespeist wird, was dem Wasser seine charakteristische Farbe verleiht. Mit einer konstanten Wassertemperatur von etwa 6 Grad Celsius friert der See auch im strengsten Winter nicht zu. Das umliegende Moorgebiet Drni ist ein wichtiger Lebensraum für zahlreiche seltene Pflanzen- und Tierarten, darunter fleischfressende Pflanzen und verschiedene geschützte Amphibien. Historisch wurde das Gebiet bereits im 19. Jahrhundert von Sir Humphry Davy, einem berühmten britischen Naturforscher, als eines der schönsten Täler Europas beschrieben. Seit 1992 steht das 47 Hektar große Gebiet unter strengem Naturschutz, um das empfindliche ökologische Gleichgewicht zu bewahren. Ein hölzerner Lehrpfad und ein Aussichtsturm ermöglichen es Besuchern, die einzigartige Flora und Fauna zu beobachten, ohne den empfindlichen Moorboden zu betreten. Von Zelenci aus bietet sich zudem ein beeindruckender Blick auf die Gipfel der Vitranc-Gruppe und der Julischen Alpen.",
      hu: "A Zelenci Természetvédelmi Terület Podkoren falu nyugati szélén található, és a Száva Dolinka, a Száva folyó egyik fő forrásvidékeként ismert. A rezervátum központi eleme egy apró, smaragdzöld tó, amelyet a krétakori tófenéken feltörő számos víz alatti forrás táplál, ami a víz jellegzetes színét adja. A tó vize állandóan 6 Celsius-fok körüli, így a legkeményebb télen sem fagy be. A tavat körülvevő Drni-mocsárvidék számos ritka növény- és állatfaj, köztük húsevő növények és védett kétéltűek fontos élőhelye. Történelmileg a területet már a 19. században felfedezte Sir Humphry Davy brit természettudós, aki Európa egyik legszebb völgyeként jellemezte a környéket. A 47 hektáros terület 1992 óta áll szigorú természetvédelem alatt az érzékeny ökológiai egyensúly megőrzése érdekében. Egy fából készült tanösvény és egy kilátótorony lehetővé teszi a látogatók számára az egyedülálló flóra és fauna megfigyelését anélkül, hogy károsítanák a mocsaras talajt. Zelenci-ből lenyűgöző kilátás nyílik a Vitranc-csoport és a Júliai-Alpok csúcsaira.",
      ro: "Rezervația Naturală Zelenci este situată la marginea vestică a satului Podkoren și este cunoscută ca fiind izvorul râului Sava Dolinka, unul dintre principalii afluenți ai Savei. Piesa centrală a rezervației este un mic lac de un verde smarald, alimentat de numeroase izvoare subterane care țâșnesc prin fundul cretos al lacului, conferind apei culoarea sa distinctivă. Cu o temperatură constantă a apei de aproximativ 6 grade Celsius, lacul nu îngheață niciodată, nici măcar în iernile cele mai aspre. Zona mlăștinoasă Drni care înconjoară lacul este un habitat vital pentru numeroase specii rare de plante și animale, inclusiv plante carnivore și diverse amfibieni protejați. Din punct de vedere istoric, zona a fost descrisă încă din secolul al XIX-lea de Sir Humphry Davy, un celebru naturalist britanic, ca fiind una dintre cele mai frumoase văi din Europa. Din 1992, suprafața de 47 de hectare este protejată strict pentru a conserva echilibrul ecologic fragil. O potecă din lemn și un turn de observare permit vizitatorilor să studieze flora și fauna unică fără a deteriora solul mlăștinos. De la Zelenci se deschide o vedere panoramică impresionantă asupra vârfurilor grupului Vitranc și ale Alpilor Iulieni.",
      en: "The Zelenci Nature Reserve is located on the western edge of the village of Podkoren and is recognized as the source of the Sava Dolinka, one of the primary headwaters of the Sava River. The centerpiece of the reserve is a small, emerald-green lake fed by numerous underwater springs emerging through the chalky lakebed, which gives the water its vibrant hue. Maintaining a constant temperature of approximately 6 degrees Celsius, the lake remains ice-free even during the harshest winters. The surrounding Drni marshland provides a crucial habitat for a variety of rare flora and fauna, including carnivorous plants and protected amphibian species. Historically, the area gained international fame in the 19th century when the British naturalist Sir Humphry Davy described it as one of the most beautiful valleys in Europe. Since 1992, the 47-hectare area has been strictly protected as a nature reserve to preserve its delicate wetland ecosystem. A system of wooden boardwalks and an observation tower allows visitors to experience the landscape without disturbing the fragile peat soil. Zelenci also offers spectacular views of the Julian Alps and the Vitranc mountain group.",
      es: "La reserva natural de Zelenci alberga el lago de manantial de color esmeralda del Save Dolinka. El agua brota de numerosas fuentes pequeñas en el fondo calcáreo del lago.",
      pt: "A reserva natural de Zelenci alberga o lago de nascente cor de esmeralda do Save Dolinka. A água brota de numerosas pequenas fontes no fundo calcário do lago.",
      fr: "La réserve naturelle de Zelenci abrite le lac de source couleur émeraude de la Save Dolinka. L'eau jaillit de nombreuses petites sources au fond calcaire du lac.",
    },
